// 生成器：树上路径加与路径最大值
//
// 每个 case type 的构造意图：
//   sample                      : 题面样例（seed=1 样例1，seed=2 样例2）
//   boundary-min                : n=1,q=1，唯一操作为查询或单点加（a_i、x 取 ±1e9 边界）
//   boundary-nearby             : n<=3 的链，最短非平凡路径 / 混合 u=v 与 u!=v
//   boundary-value              : n=1000 的链，a_i 与 x 全取 +1e9 / -1e9，卡 32 位溢出
//   boundary-large              : n 上界与 q 下界组合（seed=1 长链单查询；seed=2 双上界极值端点）
//   degenerate-chain            : 深度 n 的链（seed=1 随机端点；seed=2 恒 (1,n) 交替；seed=3 编号沿链递减）
//   degenerate-star             : 菊花图（seed=1 叶子对；seed=2 中心到叶子）
//   degenerate-binary           : 完全二叉树，叶子之间的路径操作
//   degenerate-caterpillar      : 毛毛虫（主链每点挂一片叶子）
//   degenerate-single-vertex-path: n=q=2e5，seed=1 全 u=v；seed=2 单点与 (1,n) 全链交替
//   random-large                : n=q=2e5 随机树（seed=2 权值取满 ±1e9，seed=3 加操作占 80%）
//   anti-tle                    : 卡暴力（seed=1/2 长路径加/查，seed=3 深链混合，seed=4 菊花叶子对）
//   random-small                : n,q 很小，权值含负数与 0
//   random-medium               : n,q 中等规模（seed=3 权值仅在 {-1,0,1}）
//   random-shape                : Prüfer 均匀随机树 / 偏向浅树
#include "testlib.h"
#include <vector>
#include <numeric>
#include <algorithm>
using namespace std;
using ll = long long;

const int MAXN = 200000;
const int MAXQ = 200000;
const int MAXV = 1000000000;

int n, q;

// 输出 a 数组、边、(以 edgeList 给出)
vector<pair<int,int>> edges;

void printPreamble(const vector<int>& a) {
