}

// 直接整体输出（供 sample 使用）
void emitRaw(const string& in) {
    printf("%s", in.c_str());
}

// 在输出前面先输出头信息的版本
void emitLines(int nn, int qq, const vector<int>& a, const vector<pair<int,int>>& es, const vector<string>& ops) {
    println(nn, qq);
