// ============ 树形态构造 ============

// 链：编号 1-2-...-n
vector<pair<int,int>> chainEdges(int nn, bool decreasingLabel) {
    vector<pair<int,int>> es;
    if (!decreasingLabel) {
        for (int i = 1; i <= nn - 1; i++) es.push_back({i, i + 1});
    } else {
        // 编号沿链递减：父编号大于子编号，即边 (i, i+1) 但方向反
        for (int i = 1; i <= nn - 1; i++) es.push_back({i + 1, i});
    }
    return es;
}

// 菊花：中心为 1，其余接 1
vector<pair<int,int>> starEdges(int nn) {
    vector<pair<int,int>> es;
    for (int i = 2; i <= nn; i++) es.push_back({1, i});
    return es;
}

// 随机父节点树
vector<pair<int,int>> randomTree(int nn) {
    vector<pair<int,int>> es;
    for (int i = 2; i <= nn; i++) {
        int p = rnd.next(1, i - 1);
        es.push_back({p, i});
    }
    return es;
}

// 偏向浅树的随机形态：新点接到编号较大的既有节点上
vector<pair<int,int>> shallowBiasedTree(int nn) {
    vector<pair<int,int>> es;
    for (int i = 2; i <= nn; i++) {
        // 在 [1, i-1] 中偏大取值
        int lo = max(1, i - 1 - rnd.next(0, i - 1));
        int p = rnd.next(lo, i - 1);
        es.push_back({p, i});
    }
    return es;
}

// Prüfer 序列均匀随机树
vector<pair<int,int>> pruferTree(int nn) {
    vector<pair<int,int>> es;
    if (nn == 1) return es;
    if (nn == 2) { es.push_back({1, 2}); return es; }
    vector<int> seq(nn - 2);
    for (int i = 0; i < nn - 2; i++) seq[i] = rnd.next(1, nn);
    vector<int> deg(nn + 1, 1);
    for (int x : seq) deg[x]++;
    vector<int> ptr;
    for (int i = 1; i <= nn; i++) if (deg[i] == 1) ptr.push_back(i);
    // 用小根堆不便，直接用 set 语义：排序向量 + 指针
    sort(ptr.begin(), ptr.end());
    size_t head = 0;
    for (int x : seq) {
        int leaf = ptr[head++];
        es.push_back({leaf, x});
        if (--deg[x] == 1) {
            // 插入保持有序
            ptr.push_back(x);
            // 简单插入排序到已消费位置之后
            size_t pos = ptr.size() - 1;
            while (pos > head && ptr[pos - 1] > ptr[pos]) { swap(ptr[pos - 1], ptr[pos]); pos--; }
        }
    }
    int u = -1, v = -1;
    for (int i = 1; i <= nn; i++) if (deg[i] == 1) { if (u == -1) u = i; else v = i; }
    es.push_back({u, v});
    // 随机打乱端点顺序
    for (auto& e : es) if (rnd.next(2)) swap(e.first, e.second);
    return es;
}

// 完全二叉树
vector<pair<int,int>> completeBinaryTree(int nn) {
    vector<pair<int,int>> es;
    for (int i = 2; i <= nn; i++) es.push_back({i / 2, i});
    return es;
}

// 毛毛虫：主链占一半，链上每个节点再挂一片叶子
vector<pair<int,int>> caterpillarTree(int nn) {
    vector<pair<int,int>> es;
    int spine = nn / 2;
    for (int i = 1; i < spine; i++) es.push_back({i, i + 1});
    for (int i = 1; i <= nn - spine; i++) es.push_back({i, spine + i});
    // spine >= 1 保证；若 nn 很小也成立
    return es;
}

// 随机打乱节点编号（保持边集合不变）：生成置换 p，边 (u,v)->(p[u],p[v])
void shuffleLabels() {
    vector<int> perm(n + 1);
    iota(perm.begin(), perm.end(), 0);
    // 用 [1,n] 的置换
    vector<int> idx(n);
    iota(idx.begin(), idx.end(), 1);
    ::shuffle(idx.begin(), idx.end());
    for (int i = 1; i <= n; i++) perm[i] = idx[i - 1];
    for (auto& e : edges) {
        e.first = perm[e.first];
        e.second = perm[e.second];
    }
}

