// 标准答案 ans 中逐行给出每次 2 类操作的正确最大值；
// 选手输出 ouf 应当恰好有相同行数的整数，逐行比较（64 位整数精确比较，无误差）。
#include "testlib.h"

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);

    long long expectedCount = 0;
    // 先数出 ans 里的非空答案行数
    {
        // 直接比较：ans 与 ouf 均读到 EOF
    }

    while (!ans.seekEof() && !ouf.seekEof()) {
        long long jury = ans.readLong();
        long long contestant = ouf.readLong();
        expectedCount++;
        if (jury != contestant) {
            quitf(_wa, "answer %lld differs: expected %lld, found %lld",
                  expectedCount, jury, contestant);
        }
    }

    if (!ans.seekEof()) {
        quitf(_wa, "too few answers: participant output ended early");
    }
    if (!ouf.seekEof()) {
        // 检查剩余的是否为空白
        while (!ouf.seekEof()) {
            ouf.readLong();
            quitf(_wa, "extra output beyond the expected %lld answers", expectedCount);
        }
    }

    quitf(_ok, "ok, %lld answers", expectedCount);
    return 0;
}
